export const WORDCHAIN_SCHEMA_STATEMENTS = Object.freeze([
  `CREATE TABLE IF NOT EXISTS wordchain_words (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    word TEXT NOT NULL UNIQUE,
    first_syllable TEXT NOT NULL,
    last_syllable TEXT NOT NULL,
    pos TEXT NOT NULL DEFAULT '명사',
    definition TEXT NOT NULL DEFAULT '',
    source TEXT NOT NULL DEFAULT 'kidscade',
    source_id TEXT,
    category TEXT,
    difficulty INTEGER NOT NULL DEFAULT 1,
    is_safe INTEGER NOT NULL DEFAULT 1,
    is_active INTEGER NOT NULL DEFAULT 1,
    is_proper INTEGER NOT NULL DEFAULT 0,
    is_dialect INTEGER NOT NULL DEFAULT 0,
    is_archaic INTEGER NOT NULL DEFAULT 0,
    is_technical INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  )`,
  `CREATE INDEX IF NOT EXISTS idx_wordchain_words_first
    ON wordchain_words (first_syllable, is_active, is_safe)`,
  `CREATE INDEX IF NOT EXISTS idx_wordchain_words_last
    ON wordchain_words (last_syllable, is_active)`,
  `CREATE INDEX IF NOT EXISTS idx_wordchain_words_mode
    ON wordchain_words (pos, is_safe, is_proper, is_dialect, is_archaic, is_technical, difficulty)`
]);

const schemaPromises = new WeakMap();

async function tableExists(db) {
  const row = await db.prepare(
    "SELECT name FROM sqlite_master WHERE type='table' AND name='wordchain_words' LIMIT 1"
  ).first();
  return Boolean(row);
}

async function seedCount(db) {
  const row = await db.prepare(
    "SELECT COUNT(*) AS total FROM wordchain_words WHERE source='kidscade_seed'"
  ).first();
  return Number(row?.total || 0);
}

async function seedDictionary(db) {
  if (await seedCount(db) >= WORDCHAIN_SEED.length) return;
  const chunkSize = 50;
  for (let i = 0; i < WORDCHAIN_SEED.length; i += chunkSize) {
    const chunk = WORDCHAIN_SEED.slice(i, i + chunkSize);
    const placeholders = chunk.map(() => "(?, ?, ?, '명사', 'kidscade_seed', '생활', ?, 1, 1)").join(',');
    const binds = chunk.flatMap(([word, first, last, difficulty]) => [word, first, last, difficulty]);
    await db.prepare(`
      INSERT OR IGNORE INTO wordchain_words
      (word, first_syllable, last_syllable, pos, source, category, difficulty, is_safe, is_active)
      VALUES ${placeholders}
    `).bind(...binds).run();
  }
}

export async function ensureWordchainSchema(env) {
  const db = env?.DB;
  if (!db || typeof db.prepare !== 'function' || typeof db.batch !== 'function') {
    throw new Error('wordchain-database-not-configured');
  }

  let pending = schemaPromises.get(db);
  if (!pending) {
    pending = (async () => {
      if (!(await tableExists(db))) {
        await db.batch(WORDCHAIN_SCHEMA_STATEMENTS.map(sql => db.prepare(sql)));
      }
      await seedDictionary(db);
    })().catch(error => {
      schemaPromises.delete(db);
      throw error;
    });
    schemaPromises.set(db, pending);
  }
  await pending;
}

export async function wordchainDatabaseHealth(env) {
  await ensureWordchainSchema(env);
  const row = await env.DB.prepare(
    "SELECT COUNT(*) AS total, SUM(CASE WHEN is_safe=1 AND is_active=1 THEN 1 ELSE 0 END) AS safe FROM wordchain_words"
  ).first();
  return { ok: true, database: 'ready', total: Number(row?.total || 0), safe: Number(row?.safe || 0) };
}

export { WORDCHAIN_SEED };
